'use strict';

// MODULES //

var tape = require( 'tape' );
var ctor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctor, 'function', 'main export is a function' );
	t.end();
});

tape( 'an instance throws an error if provided an invalid `lineSymbol` value', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		{},
		[ 5 ],
		[ 'circle', 5 ],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var chart = ctor();
			chart.lineSymbol = value;
		};
	}
});

tape( 'an instance supports setting and getting the property value', function test( t ) {
	var chart;

	chart = ctor({
		'lineSymbol': [ 'stroke', 'circle' ]
	});
	t.deepEqual( chart.lineSymbol, [ 'stroke', 'circle' ], 'returns expected value' );

	chart.lineSymbol = [ 'square' ];
	t.deepEqual( chart.lineSymbol, [ 'square' ], 'returns expected value' );

	t.end();
});

tape( 'an instance coerces a string value to an array containing a single value', function test( t ) {
	var chart;

	chart = ctor({
		'lineSymbol': 'circle'
	});
	t.deepEqual( chart.lineSymbol, [ 'circle' ], 'returns expected value' );

	chart.lineSymbol = 'square';
	t.deepEqual( chart.lineSymbol, [ 'square' ], 'returns expected value' );

	t.end();
});

tape( 'an instance performs a defensive copy of a provided array', function test( t ) {
	var chart;
	var arr;

	arr = [ 'stroke', 'circle' ];
	chart = ctor({
		'lineSymbol': arr
	});
	t.notEqual( chart.lineSymbol, arr, 'returns a copy' );
	t.deepEqual( chart.lineSymbol, arr, 'returns expected value' );

	arr.push( 'square' );
	t.deepEqual( chart.lineSymbol, [ 'stroke', 'circle' ], 'returns expected value' );

	t.end();
});

tape( 'setting the property updates the line symbol scale range', function test( t ) {
	var chart = ctor();

	chart.lineSymbol = [ 'stroke', 'circle' ];
	t.deepEqual( chart.lineSymbolScale.range, [ 'stroke', 'circle' ], 'returns expected value' );

	chart.lineSymbol = 'square';
	t.deepEqual( chart.lineSymbolScale.range, [ 'square' ], 'returns expected value' );

	t.end();
});

tape( 'setting the `lineSymbol` property to a new value triggers a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'lineSymbol': [ 'stroke' ]
	});

	chart.on( 'change', onChange );
	chart.lineSymbol = [ 'circle' ];

	function onChange() {
		t.ok( true, 'triggers event' );
		t.end();
	}
});

tape( 'setting the `lineSymbol` property to its current value does not trigger a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'lineSymbol': [ 'circle' ]
	});

	chart.on( 'change', onChange );
	chart.lineSymbol = [ 'circle' ];
	chart.lineSymbol = 'circle';

	t.ok( true, 'does not trigger event' );
	t.end();

	function onChange() {
		t.ok( false, 'should not trigger event' );
	}
});
